# Outlined GESA letterforms (generated by _src/make_letters.py), used in the hero and the LinkedIn cover
LETTERS = json.load(open(os.path.join(HERE, "gesa_letters.json")))


def letters_svg(cls):
    return (f'<svg class="{cls}" viewBox="0 0 {LETTERS["width"]} {LETTERS["height"]}" aria-hidden="true" focusable="false">'
            f'<path d="{LETTERS["d"]}" vector-effect="non-scaling-stroke"/></svg>')

MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"]


def nice_date(iso):
    d = datetime.date.fromisoformat(iso)
    return f"{d.day} {MONTHS[d.month - 1]} {d.year}"


def load_news():
    items = []
    for f in glob.glob(os.path.join(HERE, "news", "*.json")):
        a = json.load(open(f, encoding="utf-8"))
        if a.get("status", "published") == "published":
            items.append(a)
    items.sort(key=lambda a: (a["date"], a["slug"]), reverse=True)
    return items


NEWS = load_news()

